#pragma once
// Source-derived scaled LN1, default centeredScale=1, adaptiveScale=false.
// Prefix graphs implement fixed-state bisection; no new Custom arithmetic.
inline void readLn1Parameters(std::vector<one::Fixture>& fs){FILE* f=std::fopen("ln1-parameters.bin","rb");if(!f)throw std::runtime_error("LN1 fixture missing");uint32_t header[2];if(std::fread(header,4,2,f)!=2||header[0]!=0x314e4c47||header[1]!=24)throw std::runtime_error("LN1 header");for(unsigned i=0;i<24;++i){uint64_t anchor;if(std::fread(&anchor,8,1,f)!=1||anchor!=hashWords(fs[i].v.at("ln1"),hashWords(fs[i].v.at("layerinput"))))throw std::runtime_error("LN1 anchor");for(auto key:{"gamma1","beta1"}){auto& v=fs[i].v[key];v.resize(64);if(std::fread(v.data(),4,64,f)!=64)throw std::runtime_error("LN1 truncated");for(float x:v)if(!std::isfinite(x))throw std::runtime_error("LN1 nonfinite");}}if(std::fgetc(f)!=EOF)throw std::runtime_error("LN1 trailing");std::fclose(f);}
inline std::vector<one::Vec> ln1Stages(const one::Fixture& z,bool fp){auto round=[&](double x){return fp?double(float(x)):x;};std::vector<one::Vec> v(11);v[0].resize(32);for(unsigned row=0;row<32;++row){double sum=0;for(unsigned c=0;c<64;++c)sum=round(sum+z.v.at("layerinput")[row*64+c]);v[0][row]=round(sum/64);}
 v[1].resize(2048);for(unsigned i=0;i<2048;++i)v[1][i]=round(z.v.at("layerinput")[i]-v[0][i/64]);v[2]=v[1];v[3].resize(2048);for(unsigned i=0;i<2048;++i)v[3][i]=round(v[2][i]*v[2][i]);v[4].resize(32);for(unsigned row=0;row<32;++row){double sum=0;for(unsigned c=0;c<64;++c)sum=round(sum+v[3][row*64+c]);v[4][row]=round(sum/64);}
 v[5]=v[4];v[6].resize(32);for(unsigned row=0;row<32;++row){v[5][row]=round(v[4][row]+double(1e-5f));v[6][row]=round(1/std::sqrt(v[5][row]));}v[7]=v[6];v[8].resize(2048);v[9].resize(2048);v[10].resize(2048);for(unsigned i=0;i<2048;++i){v[8][i]=round(v[1][i]*v[7][i/64]);v[9][i]=round(v[8][i]*z.v.at("gamma1")[i%64]);v[10][i]=round(v[9][i]+z.v.at("beta1")[i%64]);}return v;}
inline unsigned ln1Frontier(const std::vector<one::Fixture>& fs){const char* names[]={"mean","center","center_scale","square","variance","variance_eps","inverse_scaled","inverse","xhat","gamma","beta"};std::vector<std::vector<one::FV>> taps(fs.size(),std::vector<one::FV>(11));
 for(int stop=-1;stop<11;++stop){bool tap=stop==-1;unsigned end=tap?10:unsigned(stop);DiagnosticGraph g("ln1prefix"+std::to_string(stop));auto x=g.tensor("layerinput",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64}),gamma=g.tensor("gamma1",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64}),beta=g.tensor("beta1",QNN_TENSOR_TYPE_APP_WRITE,{1,1,1,64});auto axis=g.constant("axis",{1},{from(3)},QNN_DATATYPE_UINT_32),one=g.constant("one",{1,1,1,1},{1.f}),eps=g.constant("epsilon",{1,1,1,1},{1e-5f});std::vector<unsigned> ids;
  for(unsigned stage=0;stage<=end;++stage){bool row=stage==0||(stage>=4&&stage<=7);auto y=g.tensor(names[stage],tap||stage==end?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,row?1u:64u});ids.push_back(y);if(stage==0||stage==4){Qnn_Param_t a=QNN_PARAM_INIT;a.name=QNN_OP_REDUCE_MEAN_PARAM_AXES;a.paramType=QNN_PARAMTYPE_TENSOR;a.tensorParam=g.tensors[axis];g.node(names[stage],QNN_OP_REDUCE_MEAN,"qti.aisw",{stage==0?x:ids[3]},{y},{a,op::boolean(QNN_OP_REDUCE_MEAN_PARAM_KEEP_DIMS,true)});}else if(stage==6)g.node(names[stage],QNN_OP_ELEMENT_WISE_RSQRT,"qti.aisw",{ids[5]},{y});else{unsigned a=0,b=0;const char* type=QNN_OP_ELEMENT_WISE_MULTIPLY;switch(stage){case 1:a=x;b=ids[0];type=QNN_OP_ELEMENT_WISE_SUBTRACT;break;case 2:a=ids[1];b=one;break;case 3:a=b=ids[2];break;case 5:a=ids[4];b=eps;type=QNN_OP_ELEMENT_WISE_ADD;break;case 7:a=ids[6];b=one;break;case 8:a=ids[1];b=ids[7];break;case 9:a=ids[8];b=gamma;break;case 10:a=ids[9];b=beta;type=QNN_OP_ELEMENT_WISE_ADD;break;}g.node(names[stage],type,"qti.aisw",{a,b},{y});}}g.finalize();
  for(auto& z:fs){auto o=g.run({{x,z.v.at("layerinput")},{gamma,z.v.at("gamma1")},{beta,z.v.at("beta1")}});auto ref=ln1Stages(z,false),fp=ln1Stages(z,true);for(unsigned stage=tap?0:end;stage<=end;++stage){auto actual=decode(o[ids[stage]]);metric(tap?"ln1Tap":"ln1Prefix",z.index,names[stage],ref[stage],fp[stage],actual,.002);unsigned lost=0;for(unsigned i=0;i<actual.size();++i)lost+=word(float(fp[stage][i]))!=o[ids[stage]][i];std::printf("ln1words,%u,%u,%u,lost=%u\n",z.index,stage,tap,lost);if(tap)taps[z.index][stage]=actual;else if(taps[z.index][stage]!=actual){std::printf("LN1_PREFIX_OBSERVER_FAIL,%u,%u\n",z.index,stage);return 3;}}}
 }return 0;
}
